-- Verifies migration 104 (saved assistant conversations are private to their member). Run through run-local.sh.
begin;
create function pg_temp.assert_true(value boolean,label text) returns void language plpgsql as $$begin if value is not true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end$$;
create function pg_temp.fails(statement text) returns boolean language plpgsql as $$begin execute statement; return false; exception when others then return true; end$$;
grant execute on function pg_temp.assert_true(boolean,text) to authenticated;
grant execute on function pg_temp.fails(text) to authenticated;
insert into auth.users(id,email) values('99000000-0000-4000-8000-000000000401','a104@test.local'),('99000000-0000-4000-8000-000000000402','b104@test.local');
insert into public.workspaces(id,name) values('99000000-0000-4000-8000-000000000403','WS 104');
insert into public.workspace_roles(id,workspace_id,name) values('99000000-0000-4000-8000-000000000404','99000000-0000-4000-8000-000000000403','Role 104');
insert into public.profiles(id,workspace_id,full_name,role_id) values('99000000-0000-4000-8000-000000000401','99000000-0000-4000-8000-000000000403','A','99000000-0000-4000-8000-000000000404'),('99000000-0000-4000-8000-000000000402','99000000-0000-4000-8000-000000000403','B','99000000-0000-4000-8000-000000000404');
insert into public.assistant_conversations(id,workspace_id,user_id,title) values('99000000-0000-4000-8000-000000000410','99000000-0000-4000-8000-000000000403','99000000-0000-4000-8000-000000000401','Chiến dịch tuần này');
insert into public.assistant_messages(workspace_id,conversation_id,user_id,role,content) values('99000000-0000-4000-8000-000000000403','99000000-0000-4000-8000-000000000410','99000000-0000-4000-8000-000000000401','user','Các chiến dịch đang chạy thế nào?'),('99000000-0000-4000-8000-000000000403','99000000-0000-4000-8000-000000000410','99000000-0000-4000-8000-000000000401','assistant','Có 34 chiến dịch đang chạy.');
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','99000000-0000-4000-8000-000000000401',true);
select pg_temp.assert_true((select count(*)=2 from public.assistant_messages),'the owner reads their messages');
update public.assistant_conversations set title='Đổi tên' where id='99000000-0000-4000-8000-000000000410';
select pg_temp.assert_true((select title='Đổi tên' from public.assistant_conversations where id='99000000-0000-4000-8000-000000000410'),'the owner renames');
select pg_temp.assert_true(pg_temp.fails($$insert into public.assistant_messages(workspace_id,conversation_id,user_id,role,content) values('99000000-0000-4000-8000-000000000403','99000000-0000-4000-8000-000000000410','99000000-0000-4000-8000-000000000401','user','x')$$),'members cannot write messages directly');
reset role;
select set_config('request.jwt.claim.sub','99000000-0000-4000-8000-000000000402',true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=0 from public.assistant_conversations) and (select count(*)=0 from public.assistant_messages),'another member sees nothing');
delete from public.assistant_conversations where id='99000000-0000-4000-8000-000000000410';
reset role;
select pg_temp.assert_true((select count(*)=1 from public.assistant_conversations where id='99000000-0000-4000-8000-000000000410'),'another member cannot delete');
select set_config('request.jwt.claim.sub','99000000-0000-4000-8000-000000000401',true);
set local role authenticated;
delete from public.assistant_conversations where id='99000000-0000-4000-8000-000000000410';
reset role;
select pg_temp.assert_true((select count(*)=0 from public.assistant_messages where conversation_id='99000000-0000-4000-8000-000000000410'),'deleting a conversation deletes its messages');
rollback;
